import { ActionSeat, ArrowLink, Card, CardColumns, Cells, ROW, type Columns } from "ui";

/** One column list, read by the headings and by a row that is its own element (a link). */
const cols: Columns = [
  "w-full tablet:w-[180px] tablet:flex-none",
  "w-full min-w-0 tablet:w-auto tablet:min-w-[160px] tablet:flex-1",
  "tablet:w-(--seat-number) tablet:flex-none tablet:text-right",
];

/**
 * A row that is not a CardRow (a link, a label) draws its parts through Cells, in the same column
 * boxes as the headings, so each heading sits over its cells.
 */
export const OnALinkRow = () => (
  <Card>
    <CardColumns cols={cols} seat="narrow">
      <span>Person</span>
      <span>Access</span>
      <span>Since</span>
    </CardColumns>
    {[
      ["Bianca Belair", "Laser cutter · Operator", "3 Nov"],
      ["Kofi Kingston", "Wood shop · Member", "28 Oct"],
    ].map(([who, what, since]) => (
      <div key={who} className={`row-divider flex flex-wrap items-center ${ROW}`}>
        <Cells cols={cols}>
          <span className="text-body font-semibold">{who}</span>
          <span className="text-body text-muted">{what}</span>
          <span className="text-small text-faint">{since}</span>
        </Cells>
        <ActionSeat seat="narrow">
          <ArrowLink href="#">Their page</ArrowLink>
        </ActionSeat>
      </div>
    ))}
  </Card>
);
